using Microsoft.Web.Administration;
using Microsoft.Web.Management.Server;
namespace JexusManager.Features.IsapiCgiRestriction { internal sealed class IsapiCgiRestrictionService : ModuleService { [ModuleServiceMethod] public IsapiCgiRestrictionSettings GetSettings() { var s = Section(); return new IsapiCgiRestrictionSettings { NotListedCgisAllowed = (bool)s["notListedCgisAllowed"], NotListedIsapisAllowed = (bool)s["notListedIsapisAllowed"] }; } [ModuleServiceMethod] public void ApplySettings(IsapiCgiRestrictionSettings settings) { var s = Section(); s["notListedCgisAllowed"] = settings.NotListedCgisAllowed; s["notListedIsapisAllowed"] = settings.NotListedIsapisAllowed; ManagementUnit.Update(); } [ModuleServiceMethod] public IsapiCgiRestrictionItem[] GetItems() { var list = new System.Collections.Generic.List<IsapiCgiRestrictionItem>(); foreach (ConfigurationElement e in Collection()) list.Add(new IsapiCgiRestrictionItem { Path = (string)e["path"], Description = (string)e["description"], Allowed = (bool)e["allowed"], Flag = e.IsLocallyStored ? "Local" : "Inhertied" }); return list.ToArray(); } [ModuleServiceMethod] public void SetAllowed(IsapiCgiRestrictionItem item, bool allowed) { var e = Find(item) ?? throw new System.InvalidOperationException("Restriction was not found."); e["allowed"] = allowed; ManagementUnit.Update(); } [ModuleServiceMethod] public void Add(IsapiCgiRestrictionItem item) { AddItem(item); ManagementUnit.Update(); } [ModuleServiceMethod] public void Update(IsapiCgiRestrictionItem oldItem, IsapiCgiRestrictionItem item) { var e = Find(oldItem); if (e != null) Collection().Remove(e); AddItem(item); ManagementUnit.Update(); } [ModuleServiceMethod] public void Remove(IsapiCgiRestrictionItem item) { var e = Find(item) ?? throw new System.InvalidOperationException("Restriction was not found."); Collection().Remove(e); ManagementUnit.Update(); } private ConfigurationSection Section() => ManagementUnit.Configuration.GetSection("system.webServer/security/isapiCgiRestriction"); private ConfigurationElementCollection Collection() => Section().GetCollection(); private ConfigurationElement Find(IsapiCgiRestrictionItem item) { foreach (ConfigurationElement e in Collection()) if ((string)e["path"] == item.Path) return e; return null; } private void AddItem(IsapiCgiRestrictionItem item) { if (item == null || string.IsNullOrWhiteSpace(item.Path)) throw new System.ArgumentException("A restriction path is required."); var e = Collection().CreateElement(); e["path"] = item.Path; e["description"] = item.Description; e["allowed"] = item.Allowed; Collection().Add(e); } } }
